rss.channel:
{{ T "feed_finished_title" }} · {{ .Site.Title }}
{{ .Permalink }}
{{ T "feed_finished_description" }} {{ .Site.Title }}
Hugo -- gohugo.io
{{ site.Language.LanguageCode }}{{ with .Site.Params.author.email }}
{{.}}{{ with $.Site.Params.author.name }} ({{.}}){{end}}{{end}}{{ with .Site.Params.author.email }}
{{.}}{{ with $.Site.Params.author.name }} ({{.}}){{end}}{{end}}{{ with .Site.Copyright }}
{{.}}{{end}}{{ if not .Date.IsZero }}
{{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}{{ end }}
{{- with .OutputFormats.Get "RSS_FINISHED" -}}
{{ printf "" .Permalink .MediaType | safeHTML }}
{{- end -}}
{{- /* One entry per viewing: the finish date plus every rewatch date. */ -}}
{{- $finished := where .Site.RegularPages "Params.status" "==" "finished" -}}
{{- /* Viewings pending review stay out of the feed until they are confirmed. */ -}}
{{- $finished = where $finished "Params.pending_review" "!=" true -}}
{{- $views := slice -}}
{{- range $finished -}}
  {{- $page := . -}}
  {{- if not .Date.IsZero -}}
    {{- $views = $views | append (dict "page" $page "date" .Date) -}}
  {{- end -}}
  {{- if reflect.IsSlice .Params.rewatches -}}
    {{- range .Params.rewatches -}}
      {{- if or (reflect.IsMap .) (not .) -}}{{- continue -}}{{- end -}}
      {{- $views = $views | append (dict "page" $page "date" (. | time.AsTime)) -}}
    {{- end -}}
  {{- end -}}
{{- end -}}
{{- $views = sort $views "date" "desc" -}}
{{- $limit := .Site.Config.Services.RSS.Limit -}}
{{- if ge $limit 1 -}}{{ $views = $views | first $limit }}{{- end -}}
{{ range $views }}
{{ partial "rss-item.html" (dict "page" .page "full" false "date" .date) }}
{{ end }}
